    let S_x = P - (P - S1) * pow(e, -(C2 * (x - S0) / P));
    let w0_x = 1. - W_f(x, 0., m);
    let w2_x = H_f(x, m + l0, m + l0);
    let w1_x = 1. - w0_x - w2_x;
    let f_x = T_x * w0_x + L_x * w1_x + S_x * w2_x;
